// Exhaust all red additions after exactly one original red edge is forbidden. Conditional seven/six test: unrestricted repeats via combinations with replacement. All seven and six demands come from optimistic upper graph; supports maximal in lower graph. Strong screens called only after fast pair screen.
#[path="ramsey_38_six_screen.rs"]mod screen;use std::io::{self,BufRead};type Bits=Vec<u64>;fn dis(x:&Bits,y:&Bits)->bool{x.iter().zip(y).all(|(i,j)|i&j==0)}fn dfs(d:usize,js:&[usize],a:&[Bits],b:&[Bits],once:&Bits,twice:&Bits)->bool{if d==0{return true}for (p,&j) in js.iter().enumerate(){if !dis(twice,&b[j]){continue}if d==1{return true}let t:Bits=twice.iter().zip(once).zip(&b[j]).map(|((x,y),z)|x|(y&z)).collect();let o:Bits=once.iter().zip(&b[j]).map(|(x,y)|x|y).collect();let next:Vec<_>=js[p..].iter().copied().filter(|&i|dis(&a[i],&a[j])&&dis(&t,&b[i])).collect();if dfs(d-1,&next,a,b,&o,&t){return true}}false}
pub fn sets(g:&[u32])->Vec<u32>{let mut v=vec![0];for (i,&x) in g.iter().enumerate(){let n=v.len();for j in 0..n{if v[j]&x==0{v.push(v[j]|1<<i)}}}v}
pub fn strong(a:&[u32],b:&[u32])->bool{let u=sets(b);if u.iter().any(|s|s.count_ones()>=8){return false}let s:Vec<_>=sets(a).into_iter().filter(|s|a.iter().enumerate().all(|(i,x)|s&(x|1<<i)!=0)).collect();let misses=|k|{let q:Vec<_>=u.iter().filter(|x|x.count_ones()==k).collect();s.iter().map(|x|{let mut m=vec![0;(q.len()+63)/64];for(i,&&y)in q.iter().enumerate(){if x&y==0{m[i/64]|=1<<(i%64)}}m}).collect::<Vec<Bits>>()};let m=misses(7);let n=misses(6);let z=vec![0;n[0].len()];dfs(7,&(0..s.len()).collect::<Vec<_>>(),&m,&n,&z,&z)}
fn tree(a:&mut Vec<u32>,ed:&[(usize,usize)],st:&mut [usize;4]){st[0]+=1;let mut b=a.clone();let es:Vec<_>=ed.iter().copied().filter(|&(i,j)|a[i]&a[j]==0).collect();for &(i,j) in &es{b[i]|=1<<j;b[j]|=1<<i}if !screen::bounds(a,&b,7,7){st[1]+=1;return}if !strong(a,&b){st[2]+=1;return}if es.is_empty(){st[3]+=1;println!("{}",a.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(" "));return}let(i,j)=es[0];tree(a,&es[1..],st);a[i]|=1<<j;a[j]|=1<<i;tree(a,&es[1..],st);a[i]^=1<<j;a[j]^=1<<i}
fn main(){for l in io::stdin().lock().lines(){let mut a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let mut bans=vec![];while a.len()>26{let hi=a.pop().unwrap()as usize;let lo=a.pop().unwrap()as usize;bans.push((hi,lo))}assert_eq!(a.len(),26);let mut e=vec![];for i in 0..a.len(){for j in 0..i{if !bans.contains(&(i,j)) && a[i]>>j&1==0 && a[i]&a[j]==0{e.push((i,j))}}}let mut st=[0;4];tree(&mut a,&e,&mut st);eprintln!("{:?}",st)}}
